param()
$ErrorActionPreference='Stop'
$project=Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'evidence-json.ps1')
$logs=Join-Path $project 'logs\continuation-20261003'
function ReadEvidence($name){Get-Content (Join-Path $logs $name) -Raw|ConvertFrom-Json}
function CheckPin($path,$sha){if((Get-FileHash $path).Hash -ne $sha){throw "Pin drift $path"}}
$c=ReadEvidence 'r436-candidate.json';CheckPin $c.path $c.sha256
if((Split-Path $c.path -Leaf) -ne 'lito-modern-r436a-host-tests.exe' -or $c.source_pins.Count -ne 15){throw 'Final candidate'}
foreach($p in $c.source_pins){CheckPin $p.path $p.sha256;CheckPin $p.snapshot $p.sha256}
$build=@(Get-Content (Join-Path $logs 'r436a-lib-build.jsonl')|ForEach-Object{try{$_|ConvertFrom-Json}catch{}})
if(-not @($build|Where-Object{$_.reason -eq 'build-finished' -and $_.success}).Count){throw 'Library incomplete'}
$rlib=@($build|Where-Object{$_.reason -eq 'compiler-artifact' -and $_.target.name -eq 'lito_modern'}|ForEach-Object{$_.filenames}|Where-Object{$_ -like '*.rlib'});if($rlib.Count -ne 1){throw 'Library count'}
$library=Join-Path (Split-Path $c.path -Parent) 'liblito_modern-r436.rlib';$sha=(Get-FileHash $rlib[0]).Hash
if(Test-Path $library){CheckPin $library $sha}else{[IO.File]::Copy($rlib[0],$library,$false);CheckPin $library $sha}
$c|Add-Member NoteProperty production_library ([ordered]@{path=$library;sha256=$sha;offline_locked=$true;target='i686-pc-windows-msvc'}) -Force
$testPath=Join-Path $logs 'r436a-consumer.stdout.log';$test=[regex]::Match([IO.File]::ReadAllText($testPath),'test result: ok\. (\d+) passed; (\d+) failed;');if(!$test.Success -or $test.Groups[1].Value -ne '4' -or $test.Groups[2].Value -ne '0'){throw 'Tests'}
$snapshot=ReadEvidence 'r436-loadout-snapshot.json';CheckPin $snapshot.handoff $snapshot.handoff_sha256
$manifestFiles=0;foreach($family in @('candidate','replay')){
 $cfg=$snapshot.$family;$mp=Join-Path $cfg.root 'manifest.json';CheckPin $mp $cfg.manifest_sha256;$m=Get-Content $mp -Raw|ConvertFrom-Json;if($m.files.Count -ne $cfg.files_verified){throw 'Manifest count'}
 foreach($p in $m.files){$path=[IO.Path]::GetFullPath((Join-Path $cfg.root $p.path));if(!$path.StartsWith($cfg.root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Manifest confinement'};if((Get-Item $path).Length -ne $p.bytes){throw 'Length'};CheckPin $path $p.sha256;$manifestFiles++}
}
if($manifestFiles -ne 3483){throw 'Snapshot total'}
$d=ReadEvidence 'r436-loadout-consumer-details.json';if($d.state -ne 'FIXED_LPL1_FULL_PROJECTION_AND_RAW_FACTS_VERIFIED_OFFLINE_ONLY' -or $d.rows.Count -ne 16 -or $d.LOADED -or $d.game_wire -or $d.authentication -or $d.query_valid_then_publish_expired_intent_race_covered){throw 'Consumer scope'}
foreach($key in @('raw_lifetimes_recomputed','signed_AC_and_MR_source_CAS_isolation','exclusive_numeric_deadline','UNARMED_never_proves_original_equipment_intent','source_and_current_flags_retained_separately')){if($d.$key -ne $true){throw "Missing boundary $key"}}
$inputs=@(foreach($family in @('candidate','replay')){
 $root=$snapshot.$family.root;$e=if($family -eq 'candidate'){Join-Path $root 'evidence'}else{$root}
 foreach($row in @($d.rows|Where-Object{$_.family -eq $family})){$lp=Join-Path $e ($row.case+'.lpl');$jp=Join-Path $e ($row.case+'.json');CheckPin $lp $row.projection_sha256;CheckPin $jp $row.full_source_facts_sha256;[ordered]@{family=$family;case=$row.case;projection=$lp;projection_sha256=$row.projection_sha256;full_source_facts=$jp;full_source_facts_sha256=$row.full_source_facts_sha256}}
})
$historical=@(foreach($name in @('r426','r427','r428','r429','r430','r431','r432','r433','r434','r435')){$old=ReadEvidence "$name-candidate.json";CheckPin $old.path $old.sha256;CheckPin $old.production_library.path $old.production_library.sha256;foreach($p in $old.source_pins){CheckPin $p.snapshot $p.sha256};[ordered]@{candidate=$name;verified_pins=2+@($old.source_pins).Count;changed=$false}})
$scope=ReadEvidence 'source-change-scope.json';if($scope.source_files -ne 497 -or $scope.new_source_files.Count -ne 18){throw 'Source scope'};foreach($p in $scope.frozen_binary_pins){CheckPin $p.path $p.sha256}
$c.validation='PASSED:4 new offline LPL1/full rawfacts tests;16 candidate/replay projections;610 lifetime views;4064 growth rows;source/owner/object/opaqueepoch/channel/revision/checksum/bounds/CAS/signedAC/MR/numeric exclusive deadline verified. Authentication/gamewire/intent publication race not qualified.'
Write-ModernEvidenceJson -Path (Join-Path $logs 'r436-candidate.json') -Value $c
$race=[ordered]@{reported_by='Supervisor update during R436';scenario='Item valid at source SQL observation expires before publication; old qualification may filter the intended item and return supported UNARMED';old_B900_B7E_coverage=$false;UNARMED_proves_equipment_intent=$false;raw_source_equipped_and_projection_flags_kept_separate=$true;desired_override_intent_before_lifetime_filter_available=$false;required='Fresh fixed Server candidate must preserve desired intent and reject/re-read any intended item that expires before publication; actual navigation Work/selection and exclusive cutoff must be independently tested';Rust_offline_projection_is_admission_authority=$false}
$appearance=[ordered]@{initial_class=0;initial_sex=0;actual_initial_weapon_instance=10304;catalog=52;retained_type=3;damage_small=17;damage_large=21;range=1;armor_instance=10305;armor_catalog=20110;reselected_object=10163;reselected_class=3;reselected_sex=0;reselected_inventory=102;reselected_weapon_facts=3;existing_profile1='Explicit unarmed prince class0/sex0/heading0or1, SCENE_ONLY';actual_equipment_absence_inferred=$false;admitted_into_profile1=$false;dependencies=@('Source-qualified equipped/desired-intent snapshot and gear revision tied to the same actual navigation owner/world publication','New authoritative renderer identity mapping actual class/sex/weapon appearance and member/range/archive/catalog pins; profile1 cannot change its immutable matrix','DarkElf class3 and additional weapon/body actions/headings plus attachment/shadow resources','Lifetime race correction and stale selection/source/generation checks before/after actual Work')}
$resultPath=Join-Path $logs 'r436-player-loadout-result.json';$handoff=Join-Path $logs 'Native-loadout-R436完整投影與裝備期限缺口交接.txt'
$result=[ordered]@{updated_at=(Get-Date).ToString('o');state='FIXED_OFFLINE_SOURCE_LOADOUT_VERIFIED_ACTUAL_WORK_INTENT_APPEARANCE_PENDING';candidate=$c;tests=@([ordered]@{passed=4;failed=0;log=$testPath;sha256=(Get-FileHash $testPath).Hash});focused_passed=4;focused_failed=0;projections=16;raw_lifetimes=($d.rows|Measure-Object inventory -Sum).Sum;weapon_facts=($d.rows|Measure-Object weapons -Sum).Sum;growth_rows=4064;snapshot=$snapshot;snapshot_files_reverified=$manifestFiles;inputs=$inputs;details=Join-Path $logs 'r436-loadout-consumer-details.json';checksum_is_authentication=$false;numeric_freshness_is_publication_intent=$false;publication_intent_race=$race;appearance_dependencies=$appearance;numerical_recomputation_scope='Existing typed strict result15 parser; complete LPL1 field equality; raw lifetime/calendar/precision/cutoff recomputation; base+modifier and saved-total AC correction for fixed neutral card/dark/greater/stone/set/armor-enchant fixtures. General equipment/proc/live-offense rules not inferred.';historical_frozen_preservation=$historical;source_scope=$scope;R434_R435_tests_rerun=$false;Rust_live_SQL_TLS=$false;producer_SQL=$true;producer_TLS=$false;game_wire=$false;complete_Physical_Source=$false;authentication=$false;renderer_LOADED=$false;full_PreparedResources=$false;GUI=0;formal_known_extensions=255;formal_R408_changed=$false;qualified_modes=16;total_modes=40}
Write-ModernEvidenceJson -Path $resultPath -Value $result
$text=@"
R436 independent Rust offline source-qualified player loadout evidence consumer
4 new tests passed/0failed; finalA host $($c.sha256), library $sha,15 frozen current source copies.3483 own copied manifest files (3452candidate+31replay) SHA/bytes/confinement reverified.16 complete LPL1/schema1 projections (eight each family),610 carried-item/raw lifetime views,62 weapon facts and4064 growth rows verify. Nested existing full result15 uses unchanged strict Rust parser and compares all owner/character/19 saved fields/every inventory field/name/template/flags against pinned JSON. Full projection source/object/opaque signed epoch/channel/gear revision/evaluation/cutoff/ownerBinding32/11effective/named modifiers/current flags/lifetimes/all carried weapons/F64 multiplier/selected weapon/reason/127+127growth match, no trailing bytes. Default runtime behavior unchanged; only test module/wiring added after R435.
Six truncation lengths, raw checksum corruption, five recomputed-checksum source/object/epoch/channel/revision substitutions and recomputed invalid support flag reject. Raw crosssource observation/instance template/lifetime substitutions reject; Gregorian leap/midnight/fraction/uncertainty/order and relative/unstarted/lighting classifications checked. Raw observation query-start epoch/nanos, DB-local now and uncertainty remain distinct; local timestamps supply only a calendar difference, no inferred timezone/epoch. Each cutoff is independently reconstructed and tested numerically at-1/exact/+1. Source/current flags are retained separately. SHA verifies evidence integrity, not authentication.
Source7/source42 share object10275 but owner bindings differ; initial/current source42 weapon remains10304/catalog52/type3,dmg17/21/range1. Source7 CAS→UNARMED revision1, real armor10305/catalog20110 revision2 changes AC2→-3/MR0→4 while source42 remains AC2/MR0/revision0. Source inventory baseline remains unchanged; saved-total AC subtracts baseline equipment before applying current equipment. Neutral-addon raw base sums and effective maxima/abilities/AC checked with signed checked arithmetic; general dark/card/greater/set/stone/armor enchant/proc/live buffs/offense not inferred. Re-selected actual source7 object10163/class3sex0/epoch8000000000000001 has102items/3weapon facts; not squeezed into29-item/class0 profile1.
CRITICAL pending provider dependency reported during R436: SQL-observed valid desired equipment can expire before publication; old qualification may filter it and return supported UNARMED. B900/B7E existing snapshots and numeric tests do not cover this new race. Numeric currentAt or a filtered UNARMED does NOT establish original desired intent or safe publication. Raw source flags and current projection flags/lifetime facts are preserved, but desired override intent before lifetime filtering is not serialized independently. Await fresh fixed Server candidate preserving intent and rejecting/requiring reread for expiry before publication; actual selected-owner navigation Work must test this boundary. Rust does not execute SQL/TLS or claim provider correction.
Appearance integration evaluation: actual initial class0/sex0 equipped weapon type3 and later armor; class3 reselected actor. Existing92/93 profile1 is immutable explicit unarmed class0/sex0 study, SCENE_ONLY never means actually no equipment. No gear appearance admitted. Need new source-qualified identity mapping class/sex/weapon/heading/actions and exact catalog/archive/member pins; actual Work source/owner/object/epoch/channel/world/gear revision/intent/deadline fences. Full Physical.Source catalogs, navigation hook/combat descriptor and renderer/shadow/attachment resources remain separate dependencies. No game wire/auth token/PLAYER/LOADED inferred from offlineLPL1.
R426-R435 fixed hosts/libraries/source snapshots and R408 preserved; R434/R435 tests not rerun.497 sources=479baseline+18new,469 unchanged/10allowed changes. FullNative/PreparedResources/rendererLOADED/playerGUI pending;mode16of40/GUI0/formalKNOWN255 unchanged. Producer actualSQL evidence only; no Rust live sockets, originalBIN or other-group writes.
Result: $resultPath
